{
  "name": "@uncle.f/free-agents",
  "version": "1.1.0",
  "description": "Free agent pack for opencode - includes Scout (fast file search) and Documenter (technical docs writer). Pro version with 5 more agents available on Gumroad.",
  "type": "module",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "scripts": {
    "build": "bun build index.ts --target=bun --outdir dist",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agents",
    "ai",
    "code-review",
    "debugger",
    "architect",
    "automation"
  ],
  "author": "uncle.fc",
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.15.0"
  },
  "engines": {
    "opencode": ">=1.0.0"
  },
  "homepage": "https://github.com/uncle-fc/free-agents",
  "repository": {
    "type": "git",
    "url": "https://github.com/uncle-fc/free-agents.git"
  },
  "bugs": {
    "url": "https://github.com/uncle-fc/free-agents/issues"
  }
}
